package cn.xinji.agentplatform.consultation.caselibrary;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import com.fasterxml.jackson.databind.JsonNode;import com.fasterxml.jackson.databind.ObjectMapper;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;
@SpringBootTest(properties={"consultation.storage=memory","spring.autoconfigure.exclude=org.springframework.boot.autoconfigure.jdbc.DataSourceAutoConfiguration"})@AutoConfigureMockMvc class CaseAnnotationWorkflowHttpApiTest{static final String U="v0-authorized-user";@Autowired MockMvc mvc;@Autowired ObjectMapper json;
 @Test void completesVersionedReviewAndWithdrawal()throws Exception{JsonNode task=json.readTree(mvc.perform(post("/api/v0/case-annotations/extractions").header("X-V0-Actor",U).contentType(MediaType.APPLICATION_JSON).content("{\"caseId\":\"CASE-SYN-001\",\"sourceVersion\":\"v1\",\"config\":\"SYNTHETIC_EXTRACT_V1\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("SUCCEEDED")).andReturn().getResponse().getContentAsString());String id=task.get("annotationId").asText();mvc.perform(post("/api/v0/case-annotations/"+id+"/revisions").header("X-V0-Actor",U).contentType(MediaType.APPLICATION_JSON).content("{\"expectedVersion\":1,\"fact\":\"人工核对事实\",\"issue\":\"争议焦点\",\"holding\":\"合成要点\",\"sourceLocation\":\"第2页第3段\",\"reason\":\"人工核对\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.version").value(2)).andExpect(jsonPath("$.state").value("DRAFT"));mvc.perform(post("/api/v0/case-annotations/"+id+"/submit").header("X-V0-Actor",U).contentType(MediaType.APPLICATION_JSON).content("{\"expectedVersion\":2}")).andExpect(jsonPath("$.state").value("PENDING_REVIEW"));mvc.perform(post("/api/v0/case-annotations/"+id+"/reviews").header("X-V0-Actor",U).contentType(MediaType.APPLICATION_JSON).content("{\"expectedVersion\":3,\"action\":\"PUBLISH\",\"reason\":\"证据位置已核对\"}")).andExpect(jsonPath("$.state").value("PUBLISHED"));mvc.perform(post("/api/v0/case-annotations/"+id+"/withdraw").header("X-V0-Actor",U).contentType(MediaType.APPLICATION_JSON).content("{\"expectedVersion\":4,\"action\":\"WITHDRAW\",\"reason\":\"测试撤回\"}")).andExpect(jsonPath("$.state").value("WITHDRAWN"));mvc.perform(get("/api/v0/case-annotations/cases/CASE-SYN-001").header("X-V0-Actor",U)).andExpect(jsonPath("$.annotations.length()").value(5)).andExpect(jsonPath("$.audits.length()").value(5));}
 @Test void replaysExtractionAndRejectsConflictAndUnauthorized()throws Exception{String body="{\"caseId\":\"CASE-SYN-002\",\"sourceVersion\":\"v1\",\"config\":\"SYNTHETIC_EXTRACT_V1\"}";String first=mvc.perform(post("/api/v0/case-annotations/extractions").header("X-V0-Actor",U).contentType(MediaType.APPLICATION_JSON).content(body)).andReturn().getResponse().getContentAsString();String id=json.readTree(first).get("annotationId").asText();mvc.perform(post("/api/v0/case-annotations/extractions").header("X-V0-Actor",U).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(jsonPath("$.annotationId").value(id));mvc.perform(post("/api/v0/case-annotations/"+id+"/revisions").header("X-V0-Actor",U).contentType(MediaType.APPLICATION_JSON).content("{\"expectedVersion\":9,\"fact\":\"x\",\"issue\":\"x\",\"holding\":\"x\",\"sourceLocation\":\"第1页\",\"reason\":\"x\"}")).andExpect(status().isConflict()).andExpect(jsonPath("$.code").value("VERSION_CONFLICT"));mvc.perform(post("/api/v0/case-annotations/extractions").header("X-V0-Actor","unknown").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isForbidden());}
}
